/** The index of the first `]` that no backslash escapes, or -1. */
function closingBracket(text, from) {
  let i = from;
  while (i < text.length) {
    if (text[i] === '\\' && i + 1 < text.length && ESCAPABLE.includes(text[i + 1])) {
      i += 2;
      continue;
    }
    if (text[i] === ']') {
      return i;
    }
    i += 1;
  }
  return -1;
}

